 final ArrayList<Channel> channels=new ArrayList<>(); final Set<String> favorites=new HashSet<>(); LinearLayout sidebar; ListView list; final ArrayList<Channel> displayed=new ArrayList<>(); PlayerView video; ExoPlayer player; TextView status; String filter="", group=""; boolean onlyFav=false; Channel current; Epg epg=new Epg(); boolean fullscreen=false; final Recorder recorder=new Recorder(); android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().addFlags(128); prefs=getSharedPreferences("vision",0); favorites.addAll(prefs.getStringSet("favorites",Collections.emptySet())); LinearLayout root=new LinearLayout(this); root.setOrientation(0); root.setBackgroundColor(0xff101722); sidebar=new LinearLayout(this); sidebar.setOrientation(1); root.addView(sidebar,new LinearLayout.LayoutParams(dp(getResources().getConfiguration().screenWidthDp<900?240:330),-1)); LinearLayout right=new LinearLayout(this); right.setOrientation(1); root.addView(right,new LinearLayout.LayoutParams(0,-1,1)); TextView title=new TextView(this); title.setText("VISION IPTV PRO"); title.setTextSize(22); title.setPadding(16,16,16,16); sidebar.addView(title); ScrollView menuScroll=new ScrollView(this); LinearLayout menu=new LinearLayout(this);menu.setOrientation(1);menuScroll.addView(menu);sidebar.addView(menuScroll,new LinearLayout.LayoutParams(-1,0,1)); button(menu,"Добавить M3U",()->new AlertDialog.Builder(this).setTitle("Добавить плейлист").setItems(new String[]{"По ссылке","Из файла","Xtream Codes"},(d,i)->{if(i==0)add();else if(i==1)pickPlaylist();else xtream();}).show()); button(menu,"Все каналы / Избранное",()->{onlyFav=!onlyFav;render();}); button(menu,"Полный экран",()->toggleFullscreen()); button(menu,"Загрузить EPG",()->epgDialog()); button(menu,"Телепрограмма",()->gridGuide()); button(menu,"Передачи канала",()->guide()); button(menu,"Плейлисты",()->playlistManager()); button(menu,"Настройки воспроизведения",()->playbackSettings()); button(menu,"Мультиэкран",()->multiView()); button(menu,"Запись / остановить",()->record()); button(menu,"Мои записи",()->recordings()); button(menu,"Пауза / перемотка",()->timeshift()); button(menu,"Фильмы и сериалы",()->vodMenu()); button(menu,"Родительский контроль",()->parental()); button(menu,"Резервная копия",()->backupMenu()); button(menu,"Обновить плейлист",()->refreshPlaylist()); button(menu,"История",()->history()); button(menu,"Группы",()->groups()); button(menu,"Поиск",()->search()); button(menu,"В избранное / удалить",()->{if(current!=null){if(!favorites.add(current.url))favorites.remove(current.url);prefs.edit().putStringSet("favorites",new HashSet<>(favorites)).apply();render();}}); list=new ListView(this);list.setOnItemClickListener((parent,view,pos,id)->play(displayed.get(pos)));sidebar.addView(list,new LinearLayout.LayoutParams(-1,0,2)); video=new PlayerView(this);right.addView(video,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(this);status.setText("Добавьте свой IPTV-плейлист");status.setPadding(16,12,16,12);right.addView(status);Button full=new Button(this);full.setText("Полный экран / список");full.setOnClickListener(v->toggleFullscreen());right.addView(full);setContentView(root); player=new ExoPlayer.Builder(this).build();video.setPlayer(player);player.addListener(new androidx.media3.common.Player.Listener(){@Override public void onPlayerError(androidx.media3.common.PlaybackException error){status.setText("Ошибка воспроизведения: "+error.getErrorCodeName());Toast.makeText(MainActivity.this,"Не удалось воспроизвести канал",Toast.LENGTH_SHORT).show();}});parse(prefs.getString("playlist",""));render();String epgUrl=prefs.getString("epgUrl","");if(!epgUrl.isEmpty())loadEpg(epgUrl); }
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
